"""Take clips generated BY HAND in Flow through the rest of the Veo stage.

    python tools/veo_manual.py <project> --part N --at K <clip.mp4> [...]
    python tools/veo_manual.py <project> --dir inbox/veo/bio5b

Everything `video veo` does except the browser: grade the frames, cut the
hallucinated tail, fit what is left to the beat's window, freeze it while each
Devanagari label is read, and write `clips_part<N>.json` so the compositor picks
it up. The output is byte-identical in shape to an automated run's, so a video
built from hand-generated clips is not a special case downstream.

WHY THIS EXISTS
---------------
Flow's UI moved. The bridge can still write a prompt, type it and press
Generate — that part is verified — but the finished clip is no longer reachable
from the DOM: the grid is virtualised and lazily loaded, finished clips render
as <img> rather than <video>, and neither URL family in the page is the video
(the /image/ keys are 0.03 MB poster stills and the /asb/ keys do not download
at all). Reverse-engineering that is worth doing once, calmly; it is not worth
blocking a video on.

So: generate in Flow by hand, drop the files here, and the pipeline continues.
The prompts are written for you — `projects/<slug>/veo/prompts.json`, one per
beat, already audited.

NAMING, for the --dir form
--------------------------
    part<N>_at<K>.mp4        e.g. part1_at040.mp4
`at` is the CAPTION INDEX the beat is anchored to, not a timestamp — the same
number that is in beats_part<N>.json.
"""
from __future__ import annotations

import argparse
import json
import re
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from src import (veo, veo_conform, veo_delogo, veo_holds, veo_labels,  # noqa: E402
                 veo_qc)


def specs_for(root: Path) -> dict[tuple[int, int], dict]:
    """The written prompts, keyed by (part, at), so the review has its checks.

    Without them `veo_qc.review` grades against the house contract only, and the
    checks are the half that knows this beat asked for a Y-shaped junction.
    """
    f = root / "veo" / "prompts.json"
    if not f.is_file():
        return {}
    return {(int(p["part"]), int(p["at"])): p
            for p in json.loads(f.read_text(encoding="utf-8"))}


def one(root: Path, part: int, at: int, src: Path, *, provider: str | None,
        specs: dict, accept=None, good_until_override=None) -> dict:
    beats, lines, meta = veo.video_beats(root, part)
    beat = next((b for b in beats if int(b["at"]) == at), None)
    if beat is None:
        raise SystemExit(f"part {part} has no video beat at caption {at}; "
                         f"it has {[int(b['at']) for b in beats]}")
    clip_end = float(meta["clip_end"][str(part)])
    start, end = veo.window(beat, beats, lines, clip_end)

    out_dir = root / "veo"
    out_dir.mkdir(parents=True, exist_ok=True)
    raw = out_dir / f"part{part}_at{at:03d}_raw.mp4"
    if src.resolve() != raw.resolve():
        shutil.copy2(src, raw)

    frame = veo.veo_prompts.frame_of(beat)
    layout = veo.veo_prompts.layout_of(beat)
    backdrop = veo.veo_prompts.backdrop_of(beat)
    spec = specs.get((part, at)) or {"prompt": beat["brief"], "checks": []}

    print(f"\n=== part{part} beat@{at} — {raw.name} "
          f"({veo_conform.duration(raw):.1f}s generated, "
          f"{end - start:.2f}s window) ===")
    clean, mark = veo_delogo.strip(raw, out_dir / f"part{part}_at{at:03d}_clean.mp4")
    if mark:
        print(f"  removed Flow's marker at {mark}")
    raw = clean

    review = veo_qc.review(raw, spec, work=out_dir / "review", brief=beat["brief"],
                           frame=frame, plate=None, green=(backdrop == "green"),
                           layout=layout, backdrop=backdrop,
                           style=veo.veo_prompts.style_of(beat), provider=provider)
    print(f"  review: {review['verdict']} — {review.get('summary', '')}")
    for d in review.get("defects") or []:
        print(f"    - [{d.get('severity')}] {d.get('issue')}")

    motion = beat.get("motion", "one_way")
    if motion == "cyclic" and not review.get("loopable"):
        print("  ⚠ the beat says cyclic but the review says it does not return to "
              "where it started; holding the final state instead")
        motion = "settling"

    fitted = out_dir / f"part{part}_at{at:03d}.mp4"
    try:
        holds = veo_holds.plan(beat, lines, start, end)
    except ValueError as exc:
        print(f"  ⚠ {exc} — the pauses are dropped for this beat")
        holds = []
    need = veo_holds.content_seconds(end - start, holds)
    if holds:
        print(f"  {len(holds)} label pause(s): {need:.1f}s of motion + "
              f"{sum(h['hold'] for h in holds):.1f}s frozen = {end - start:.1f}s")
    # An accepted clip is accepted WHOLE. `good_until` is how far the grader
    # trusts the picture, and a grader that failed the clip sets it to zero — so
    # conform then refuses, saying there is nothing to stretch. Overriding the
    # verdict without this makes the flag useless: it would mark the clip usable
    # and still leave it unfitted, which is the worst of both.
    good_until = review.get("good_until")
    if good_until_override:
        good_until = good_until_override
        print(f"  --good-until: keeping the first {good_until:.1f}s, "
              f"cutting the rest")
    elif accept and not good_until:
        good_until = veo_conform.duration(raw)
        print(f"  --accept: taking the whole {good_until:.1f}s as usable "
              f"(the grader trusted none of it)")

    try:
        fit = veo_conform.conform(raw, fitted, good_until=good_until,
                                  need=need, strategy=motion)
        if holds:
            held = fitted.with_name(fitted.stem + "_held.mp4")
            veo_holds.apply_holds(fitted, holds, held)
            held.replace(fitted)
        print(f"  fitted: {fit['had']}s generated, {fit['usable']}s usable"
              + (f" ({fit['trimmed']}s of tail cut)" if fit["trimmed"] > 0.05 else "")
              + f" -> {fit['need']}s on screen by {motion}")
    except veo_conform.ConformError as exc:
        print(f"  ⚠ could not fit this clip to its window: {exc}")
        fit, fitted = None, raw
        review["verdict"] = "fail"

    labels = veo_labels.build(beat, lines, start, end, out_dir / "labels",
                              f"part{part}_at{at:03d}")
    for a in labels:
        a["png"] = str(Path(a["png"]).relative_to(root))
    for bad in veo.label_faults(labels, frame=frame, band=veo.panel_band(beat)):
        print(f"  ⚠ {bad}")

    return {
        "at": at, "start": round(start, 2), "end": round(end, 2),
        "src": str(fitted.relative_to(root)), "raw": str(raw.relative_to(root)),
        "full": frame == "full", "frame": frame, "layout": layout,
        "green": backdrop == "green", "backdrop": backdrop,
        "panel_ar": beat.get("panel_ar"), "panel_top": beat.get("panel_top"),
        "labels": labels, "fit": fit, "verdict": review["verdict"],
        "attempts": 1, "sequence": beat.get("sequence"), "continues_from": None,
        "continuity": None, "reference": None,
        "usable": review["verdict"] != "fail" or bool(accept),
        "by_hand": True,
        # An override is RECORDED, never silent. The grader marks a clip against
        # the brief it was given, and a brief can be revised after the clip was
        # graded — this one's supercoiling shot was failed for having no Y-shaped
        # fork, months before "do not add a fork" was written into the brief.
        # Overriding on that basis is a judgement, so it is written down with its
        # reason and the verdict it overrode is left standing beside it.
        **({"accepted_by_hand": accept, "overrode_verdict": review["verdict"]}
           if accept and review["verdict"] == "fail" else {}),
    }


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("project")
    ap.add_argument("clips", nargs="*", help="clip files, with --part/--at")
    ap.add_argument("--part", type=int)
    ap.add_argument("--at", type=int)
    ap.add_argument("--dir", help="a folder of part<N>_at<K>.mp4 files")
    ap.add_argument("--provider")
    ap.add_argument("--good-until", type=float, metavar="SECONDS",
                    help="the clip is right up to here and wrong after it; the "
                         "rest is cut and what is left is fitted to the window. "
                         "Use when a generation gets the action right and then "
                         "undoes it — a helix that relaxes and then re-coils "
                         "teaches the process backwards if the tail is kept.")
    ap.add_argument("--accept", metavar="REASON",
                    help="keep a clip the grader failed, recording WHY. For a "
                         "brief that changed after the grading, not for a clip "
                         "that is simply wrong.")
    a = ap.parse_args()

    root = veo.resolve(a.project)
    specs = specs_for(root)
    if not specs:
        print("  ! no veo/prompts.json — the review will grade against the house "
              "contract only, not against this beat's own checks")

    jobs: list[tuple[int, int, Path]] = []
    if a.dir:
        for f in sorted(Path(a.dir).glob("part*_at*.mp4")):
            m = re.match(r"part(\d+)_at(\d+)", f.stem)
            if m:
                jobs.append((int(m.group(1)), int(m.group(2)), f))
        if not jobs:
            raise SystemExit(f"no part<N>_at<K>.mp4 files in {a.dir}")
    else:
        if a.part is None or a.at is None or len(a.clips) != 1:
            raise SystemExit("give one clip with --part and --at, or use --dir")
        jobs = [(a.part, a.at, Path(a.clips[0]))]

    done: dict[int, list[dict]] = {}
    for part, at, f in jobs:
        done.setdefault(part, []).append(
            one(root, part, at, f, provider=a.provider, specs=specs,
                accept=a.accept, good_until_override=a.good_until))

    for part, recs in done.items():
        out = root / f"clips_part{part}.json"
        # MERGE, never overwrite: a part is often finished one clip at a time,
        # and rewriting the file would silently drop the clips already done.
        existing = (json.loads(out.read_text(encoding="utf-8"))
                    if out.is_file() else [])
        keep = [c for c in existing if c["at"] not in {r["at"] for r in recs}]
        merged = sorted(keep + recs, key=lambda c: c["at"])
        out.write_text(json.dumps(merged, ensure_ascii=False, indent=2),
                       encoding="utf-8")
        bad = [c for c in merged if not c["usable"]]
        print(f"\npart {part}: {len(merged)} clip(s) -> {out.name}"
              + (f"  ({len(bad)} did not pass the review)" if bad else ""))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
